    {
      "card_ids": ["C14"],
      "claim": "Rifapentine has an absolute oral bioavailability of 70% after a single 600 mg dose in healthy volunteers, supporting a high prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is palbociclib, a pyrido[2,3-d]pyrimidinone CDK inhibitor. All high-transfer experimental analogues have measured absolute oral bioavailability values of 28-100%, with the closest structural analogue brigatinib at 46%; no affirmative threshold-relevant evidence supports F < 20%. Therefore the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is included in the supplied evidence.",
    "Encainide shows wide interindividual bioavailability variability and paliperidone bioavailability is formulation-dependent, but central estimates remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

